/// that names the file on disk.
pub fn validate_wire_name(wire_path: &str, raw: Option<&[u8]>) -> Result<PathBuf> {
    match raw {
        Some(raw) => validate_wire_path_bytes(raw),
        None => validate_wire_path(wire_path),
    }
}

